 "content": "def transform(grid):
    """Recolor the largest zero component 8 and the smallest one 7."""
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append(cells)
    if components:
        largest = max(components, key=len)
        smallest = min(components, key=len)
        for r, c in largest:
            out[r][c] = 8
        for r, c in smallest:
            out[r][c] = 7
    return out

